data = json.load(open('employee_data.json'))
relocation_yes = str(data.get('RELOCATION_PACKAGE','')).strip().lower() == 'yes'

pattern = re.compile(r'\{\{([A-Z_]+)\}\}')


def process_paragraph(p):
    text = p.text
    # Handle conditional relocation section
    if 'IF_RELOCATION' in text and 'END_IF_RELOCATION' in text:
        start = text.find('{{IF_RELOCATION}}')
        end = text.find('{{END_IF_RELOCATION}}')
        if start != -1 and end != -1 and end > start:
            content = text[start+len('{{IF_RELOCATION}}'):end]
            if relocation_yes:
                text = content
            else:
                text = ''
    # Replace placeholders
    matches = pattern.findall(text)
    if matches:
        new_text = text
        for key in matches:
            placeholder = '{{' + key + '}}'
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))
            else:
                # remove any unmatched placeholders (e.g., IF/END)
                new_text = new_text.replace(placeholder, '')
        text = new_text
    # Update paragraph if changed
    if p.text != text:
        if p.runs:
            p.runs[0].text = text
            for run in p.runs[1:]:
                run.text = ''
        else:
            p.add_run(text)


def process_paragraphs(paragraphs):
    for p in paragraphs:
        process_paragraph(p)


def process_tables(tables):
    for table in tables:
        for row in table.rows:
            for cell in row.cells:
                process_paragraphs(cell.paragraphs)
                if cell.tables:
                    process_tables(cell.tables)

# Load document
doc = Document('offer_letter_template.docx')

# Process body
process_paragraphs(doc.paragraphs)
process_tables(doc.tables)

# Process headers/footers
for section in doc.sections:
    process_paragraphs(section.header.paragraphs)
    process_paragraphs(section.footer.paragraphs)
    process_tables(section.header.tables)
    process_tables(section.footer.tables)

# Save output
output_path = '/root/offer_letter_filled.docx'
doc.save(output_path)
print('Saved', output_path)
